<script lang="ts">
export default {options:{styleIsolation:'shared'}}
</script>
<script setup lang="ts">
import DecorationAction from './DecorationAction.vue'
import {computed} from 'vue'
import type {DecorationBlock,DecorationLink} from '@qicore/application-sdk/browser/decoration-types'
import {decorationOptions,visibleDecorationItems} from '@qicore/application-sdk/browser/decoration-options.mjs'
import {frameworkAsset as sharedFrameworkAsset,decorationIcons} from '@qicore/application-sdk/browser/decoration-framework.mjs'
const frameworkAsset=(name:string)=>(import.meta.env.UNI_PLATFORM==='h5'?'/h5-assets':'')+sharedFrameworkAsset(name,true)
const props=defineProps<{block:DecorationBlock;editable?:boolean;images:Record<string,string>}>()
const emit=defineEmits<{navigate:[target:DecorationLink]}>()
const o=computed(()=>decorationOptions(props.block)),items=computed(()=>visibleDecorationItems(props.block))
const imageUrl=(id:string)=>props.images[id]||''
const icon=(name:string|undefined,blue=false)=>frameworkAsset('icons/'+(decorationIcons.includes(name||'')?name:'layout-grid')+(blue?'-blue':'')+'.svg')
function go(target:DecorationLink){if(!props.editable&&target)emit('navigate',target)}
</script>
<template><view v-if="block.type==='intro'" class="fw-section framework-intro qc-view" :style="{backgroundImage:'url('+(block.imageId?imageUrl(block.imageId):frameworkAsset('intro.png'))+')'}"><view class="fw-paragraph intro-eyebrow qc-view">{{o.eyebrow}}</view><view class="fw-heading qc-view">{{block.title}}</view><view class="fw-paragraph intro-description qc-view">{{block.text}}</view><DecorationAction :target="block.target" :native-disabled="editable" root-class="fw-control intro-action" role="button" @click="go(block.target)">{{o.buttonText}}<image mode="aspectFit" :src="icon('arrow-right',true)" alt="" class="qc-image"/></DecorationAction></view>
<view v-else-if="block.type==='features'" class="fw-section framework-features qc-view"><view v-if="block.title" class="fw-heading qc-view">{{block.title}}</view><view class="fw-div features-grid qc-view"><DecorationAction :target="item.target" :native-disabled="editable" root-class="fw-control" v-for="item in items" :key="item.id" role="button" :disabled="!item.target" @click="go(item.target)"><view class="fw-span feature-icon qc-view"><image mode="aspectFit" :src="item.imageId?imageUrl(item.imageId):icon(item.icon,true)" alt="" class="qc-image"/></view><view class="fw-strong qc-view">{{item.label}}</view><view v-if="item.text" class="fw-span feature-description qc-view">{{item.text}}</view></DecorationAction></view><view v-if="block.text" class="fw-paragraph features-footer qc-view">{{block.text}}</view></view>
<view v-else-if="block.type==='orders'" class="fw-section framework-orders qc-view"><view class="fw-header qc-view"><view class="fw-heading qc-view">{{block.title}}</view><DecorationAction :target="block.target" :native-disabled="editable" v-if="block.target" role="button" root-class="fw-control section-more" @click="go(block.target)">全部订单<image mode="aspectFit" :src="icon('chevron-right')" alt="" class="qc-image"/></DecorationAction><view v-else-if="editable" class="order-setup qc-view">请选择订单入口</view></view><view v-if="items.length" class="fw-div order-shortcuts qc-view" :style="{gridTemplateColumns:'repeat('+Math.min(items.length,4)+',minmax(0,1fr))'}"><DecorationAction :target="item.target" :native-disabled="editable" root-class="fw-control" v-for="item in items" :key="item.id" role="button" @click="go(item.target)"><view class="order-shortcut-icon qc-view"><image mode="aspectFit" :src="item.imageId?imageUrl(item.imageId):icon(item.icon,true)" alt="" class="qc-image"/></view><view class="fw-span qc-view">{{item.label}}</view></DecorationAction></view></view>
</template>
